         int: Index of the first element that matches the target. If no match is found, returns -1.
     """
     if len(arr) == 0:
         return -1
     start = 0
     end = len(arr)-1
     while start <= end:
         mid = (start+end)/2
         if arr[mid] < target:
             start = mid + 1
         else:
             end = mid

     if arr[start] == target:
         return start
     elif arr[end] == target:
         return end
     else:
         return -1


