 """
    Quick sort function.

    Args:
        arr (list): list to be sorted

    Returns:
        list: sorted array
    """
    if len(arr) <= 1:
        return arr

    pivot = arr[0]
    low, high = 0, len(arr)-1
    while low < high:
        while low < high and arr[low] > pivot:
            low += 1

        while low < high and arr[high] < pivot:
            high -= 1

        if low < high:
            arr[low], arr[high] = arr[high], arr[low]

    return quicksort(arr[:low]) + [pivot] + quicksort(arr[low+1:])

